'use strict';
(async()=>{const id=location.pathname.split('/').pop(),message=document.getElementById('print-message');try{API.csrfToken=(await API.request('/auth/csrf',{method:'POST',body:{}})).csrfToken;const d=await API.request('/labels/jobs/'+id);function history(data){const el=document.getElementById('print-history');if(!el)return;el.replaceChildren();for(const e of data.events){const li=document.createElement('li');li.textContent=e.occurred_at+' · '+e.action+' · '+e.reason;el.append(li);}}history(d);for(const x of d.items){const a=document.createElement('article');a.className='label';const img=document.createElement('img');img.src=x.image;img.alt=x.id;const no=document.createElement('strong');no.textContent=x.id;const environment=document.createElement('small');environment.textContent=d.environment==='test'?'DEMO / TEST · 非真实库存':'MUSONOI';a.append(environment,img,no);document.getElementById('labels').append(a);}document.getElementById('print-labels').onclick=async e=>{e.target.disabled=true;try{await API.request('/labels/jobs/'+id+'/print',{method:'POST',body:{reason:document.getElementById('print-reason').value},idempotencyKey:crypto.randomUUID()});history(await API.request('/labels/jobs/'+id));message.textContent='服务器已记录打印请求，物理打印状态以打印机为准 / Print request logged';window.print();}catch(e){message.textContent=e.message;}finally{e.target.disabled=false;}};document.getElementById('export-labels').onclick=async e=>{e.target.disabled=true;try{const r=await API.request('/labels/jobs/'+id+'/export',{method:'POST',body:{},binary:true,idempotencyKey:crypto.randomUUID()}),url=URL.createObjectURL(r.blob),link=document.createElement('a');link.href=url;link.download='musonoi-bundle-labels.xlsx';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){message.textContent=e.message;}finally{e.target.disabled=false;}};}catch(e){message.textContent=e.message;document.querySelectorAll('button').forEach(b=>b.disabled=true);}})();
